<script setup>import{onMounted,reactive,ref}from'vue';import api from '../services/api';const form=reactive({vat_rate:0,invoice_prefix:'INV',payment_methods:['cash','bank','bkash','nagad']});const notice=ref('');onMounted(async()=>{const data=(await api.get('/settings')).data.data;Object.assign(form,data,{payment_methods:data.payment_methods?JSON.parse(data.payment_methods):form.payment_methods})});const save=async()=>{await api.put('/settings',{settings:form});notice.value='সেটিংস সংরক্ষিত হয়েছে।'}</script><template><section class="page-card"><div class="page-heading"><div><p class="eyebrow">ADMIN SETTINGS</p><h2>সিস্টেম সেটিংস</h2><p>VAT, ইনভয়েস নম্বর এবং পেমেন্ট মাধ্যম কনফিগার করুন।</p></div></div><form class="form-grid" @submit.prevent="save"><label>VAT হার (%)<input v-model.number="form.vat_rate" type="number" min="0" max="100" /></label><label>ইনভয়েস প্রিফিক্স<input v-model="form.invoice_prefix" /></label><label class="full-width">পেমেন্ট মাধ্যম<div class="checks"><label v-for="method in ['cash','bank','bkash','nagad']"><input v-model="form.payment_methods" type="checkbox" :value="method" />{{method}}</label></div></label><div class="full-width form-actions"><span class="success">{{notice}}</span><button class="primary">সেটিংস সংরক্ষণ করুন</button></div></form></section></template>
